and private encNode (n: Node<'Msg>) : JVal =
    let kind = encNodeKind n.Kind

    JObj([ Some("id", JStr n.Id); Some("kind", kind); (n.Accessibility |> Option.map (fun v -> "accessibility", encAccessibility v)); None; (n.Fallback |> Option.map (fun v -> "fallback", encNode v)); None; (n.State |> Option.map (fun v -> "state", encStateBehaviour v)); (n.Style |> Option.map (fun v -> "style", encSemanticStyle v)); (n.Tooltip |> Option.map (fun v -> "tooltip", encTextSource v)); (n.Visible |> Option.map (fun v -> "visible", (encBinding JBool) v)) ] |> List.choose id)

and private encAction<'Msg> (v: Action<'Msg>) : JVal =
    match v with
    | Action.Chain ops -> Canonical.typed "Chain" [ "ops", JArr(List.map encAction ops) ]
    | Action.WriteToClipboard text -> Canonical.typed "WriteToClipboard" [ "text", encTextSource text ]
    | Action.Dispatch msg -> Canonical.typed "Dispatch" ([ None ] |> List.choose id)
    | Action.Invoke (capabilityId, args) -> Canonical.typed "Invoke" [ "capabilityId", JStr capabilityId; "args", JArr(List.map encInvokeArg args) ]
    | Action.ReadFileBody (fileRef, fileHandle, encoding, onRead) -> Canonical.typed "ReadFileBody" ([ Some("fileRef", JStr fileRef); None; Some("encoding", encFileReadEncoding encoding); (onRead |> Option.map (fun v -> "onRead", JStr "<closure>")) ] |> List.choose id)
    | Action.Call (endpoint, onResult, into) -> Canonical.typed "Call" ([ Some("endpoint", JStr endpoint); (onResult |> Option.map (fun v -> "onResult", JStr "<closure>")); (into |> Option.map (fun v -> "into", encCallResultTarget v)) ] |> List.choose id)
    | Action.Navigate (route, target) -> Canonical.typed "Navigate" ([ Some("route", encTextSource route); (if target = NavigateTarget.Self then None else Some("target", encNavigateTarget target)) ] |> List.choose id)
    | Action.CommitLocal nodeId -> Canonical.typed "CommitLocal" [ "nodeId", JStr nodeId ]
    | Action.Notify (channel, payload) -> Canonical.typed "Notify" [ "channel", JStr channel; "payload", id payload ]
    // Phase 818 — `value` / `valueFrom` are XOR siblings; each is emitted only
    // when present (Canon sorts keys, so the field order stays alphabetical).
    | Action.SetState (key, value, valueFrom) -> Canonical.typed "SetState" ([ Some("key", JStr key); (value |> Option.map (fun v -> "value", id v)); (valueFrom |> Option.map (fun v -> "valueFrom", (encBinding id) v)) ] |> List.choose id)
    | Action.AiTool (toolName, args) -> Canonical.typed "AiTool" [ "toolName", JStr toolName; "args", id args ]
    | Action.Print -> Canonical.typed "Print" [  ]
    | Action.Confirm (prompt, onConfirm, onCancel) -> Canonical.typed "Confirm" ([ Some("prompt", encTextSource prompt); Some("onConfirm", encAction onConfirm); (onCancel |> Option.map (fun v -> "onCancel", encAction v)) ] |> List.choose id)
    | Action.Focus nodeId -> Canonical.typed "Focus" [ "nodeId", JStr nodeId ]

and private encBinding<'T> (encT: 'T -> JVal) (v: Binding<'T>) : JVal =
    match v with
    | Binding.Static value -> Canonical.typed "Static" ([ (value |> Option.map (fun v -> "value", encT v)) ] |> List.choose id)
    | Binding.Query (name, accessor, dependsOn) -> Canonical.typed "Query" ([ Some("name", JStr name); None; (dependsOn |> Option.map (fun v -> "dependsOn", JArr(List.map JStr v))) ] |> List.choose id)
    | Binding.Filter (name, defaultValue) -> Canonical.typed "Filter" ([ Some("name", JStr name); (defaultValue |> Option.map (fun v -> "defaultValue", encT v)) ] |> List.choose id)
    | Binding.Selection (nodeId, accessor, defaultValue, field) -> Canonical.typed "Selection" ([ Some("nodeId", JStr nodeId); None; (defaultValue |> Option.map (fun v -> "defaultValue", encT v)); (field |> Option.map (fun v -> "field", JStr v)) ] |> List.choose id)
    | Binding.State (key, defaultValue) -> Canonical.typed "State" ([ Some("key", JStr key); (defaultValue |> Option.map (fun v -> "defaultValue", encT v)) ] |> List.choose id)
    | Binding.Now (accessor, grain) -> Canonical.typed "Now" ([ None; (grain |> Option.map (fun v -> "grain", encTimeGrain v)) ] |> List.choose id)
    | Binding.Computed fn -> Canonical.typed "Computed" [ "fn", JStr "<closure>" ]
    | Binding.Local (flushOn, format, initialFrom, onCommit, parse, codec, commitTo) -> Canonical.typed "Local" ([ Some("flushOn", encLocalFlushTrigger flushOn); Some("format", JStr "<closure>"); Some("initialFrom", (encBinding encT) initialFrom); (onCommit |> Option.map (fun v -> "onCommit", JStr "<closure>")); Some("parse", JStr "<closure>"); (codec |> Option.map (fun v -> "codec", encFormat v)); (commitTo |> Option.map (fun v -> "commitTo", JStr v)) ] |> List.choose id)
    | Binding.Format (source, format, locale) -> Canonical.typed "Format" [ "source", (encBinding encFloat) source; "format", encFormat format; "locale", encLocaleSource locale ]
    | Binding.I18n (key, args) -> Canonical.typed "I18n" ([ Some("key", JStr key); (args |> Option.map (fun v -> "args", (fun __m -> JObj(Map.toList __m |> List.map (fun (k, v) -> k, (encBinding id) v))) v)) ] |> List.choose id)
    | Binding.Transform (source, pipeline, ``params``) -> Canonical.typed "Transform" ([ Some("source", encTransformSource source); Some("pipeline", JArr(List.map Fuaran.Compute.DataFrameCodec.encodeTransform pipeline)); (``params`` |> Option.map (fun v -> "params", JArr(List.map encTransformParam v))) ] |> List.choose id)
    | Binding.Expr (expr, ``params``) -> Canonical.typed "Expr" ([ Some("expr", Fuaran.Compute.DataFrameCodec.encodeExpr expr); (``params`` |> Option.map (fun v -> "params", JArr(List.map encTransformParam v))) ] |> List.choose id)
