    | FormFieldKind.RangedNumber (value, onChange, min, max, step) -> Canonical.typed "RangedNumber" ([ (value |> Option.map (fun v -> "value", (encBinding id) v)); (onChange |> Option.map (fun v -> "onChange", JStr "<closure>")); (min |> Option.map (fun v -> "min", encFloat v)); (max |> Option.map (fun v -> "max", encFloat v)); (step |> Option.map (fun v -> "step", encFloat v)) ] |> List.choose id)
    | FormFieldKind.Range (value, onChange, min, max, step) -> Canonical.typed "Range" ([ (value |> Option.map (fun v -> "value", (fun (v: Binding<JVal>) -> match v with | Binding.Static(Some p) -> p | __other -> encBinding id __other) v)); (onChange |> Option.map (fun v -> "onChange", JStr "<closure>")); (min |> Option.map (fun v -> "min", encFloat v)); (max |> Option.map (fun v -> "max", encFloat v)); (step |> Option.map (fun v -> "step", encFloat v)) ] |> List.choose id)
    | FormFieldKind.SegmentedChoice (options, value, onChange, orientation) -> Canonical.typed "SegmentedChoice" ([ Some("options", (encBinding (fun __xs -> JArr(List.map encSelectOption __xs))) options); (value |> Option.map (fun v -> "value", (encBinding id) v)); (onChange |> Option.map (fun v -> "onChange", JStr "<closure>")); (if orientation = Orientation.Horizontal then None else Some("orientation", encOrientation orientation)) ] |> List.choose id)
