    | FormFieldKind.DateTimeRange (value, onChange, variant, min, max, step) -> Canonical.typed "DateTimeRange" ([ (value |> Option.map (fun v -> "value", (fun (v: Binding<JVal>) -> match v with | Binding.Static(Some p) -> p | __other -> encBinding id __other) v)); (onChange |> Option.map (fun v -> "onChange", JStr "<closure>")); Some("variant", encDateTimeVariant variant); (min |> Option.map (fun v -> "min", JStr v)); (max |> Option.map (fun v -> "max", JStr v)); (step |> Option.map (fun v -> "step", encFloat v)) ] |> List.choose id)
