    | FormFieldKind.Color (onChange, value) -> Canonical.typed "Color" ([ (onChange |> Option.map (fun v -> "onChange", JStr "<closure>")); (value |> Option.map (fun v -> "value", (encBinding id) v)) ] |> List.choose id)
