and private decCellFormat (j: JVal) : Result<CellFormat, DecodeError> =
    match j with
    | JObj __fs ->
        dTag __fs |> Result.bind (fun __t ->
        match __t with
        | "None" -> Ok CellFormat.None
        | "Number" ->
            dOpt "decimals" __fs dInt |> Result.bind (fun decimals ->
            dOpt "locale" __fs decLocaleSource |> Result.bind (fun locale ->
            Ok(CellFormat.Number(decimals, locale))))
        | "Currency" ->
            dReq "code" __fs dStr |> Result.bind (fun code ->
            dOpt "decimals" __fs dInt |> Result.bind (fun decimals ->
            dOpt "locale" __fs decLocaleSource |> Result.bind (fun locale ->
            Ok(CellFormat.Currency(code, decimals, locale)))))
        | "Percent" ->
            dOpt "decimals" __fs dInt |> Result.bind (fun decimals ->
            dOpt "locale" __fs decLocaleSource |> Result.bind (fun locale ->
            Ok(CellFormat.Percent(decimals, locale))))
        | "SignificantDigits" ->
            dReq "digits" __fs dInt |> Result.bind (fun digits ->
