/// Phase 377 — the public per-spec decoders. `decode<Tag>Spec` reads one kind's object and
/// answers its FIRST defect; `decode<Tag>SpecAll` reads the same object and answers EVERY defect,
/// in the order stated above the collecting prelude. A consumer delegates one kind at a time.
/// Phase 541 — `decode<Tag>SpecAllWith` reads it through a host's `CollectingDecoders`, so the
/// host's decoder at a type applies at every depth; `decode<Tag>SpecAll` is its no-override case.
let decodeBadgeSpec (j: JVal) : Result<BadgeSpec, DecodeError> = decBadgeSpec j
let decodeBadgeSpecAll (j: JVal) : Result<BadgeSpec, DecodeError list> = colBadgeSpec collectingDecoders j
let decodeBadgeSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<BadgeSpec, DecodeError list> =
    decoders.BadgeSpec decoders j
