/// `decodeNode`'s collecting twin: a parser refusal is the one defect, else every defect.
let decodeNodeAll (s: string) : Result<Node<obj>, DecodeError list> =
    Decoder.parse ReadOptions.strict s |> cOne |> Result.bind (colNode collectingDecoders)
let decodeNodeAllWith (decoders: CollectingDecoders) (s: string) : Result<Node<obj>, DecodeError list> =
    Decoder.parse ReadOptions.strict s |> cOne |> Result.bind (decoders.Node decoders)